script:
(function () {
  'use strict';
  // HSA-eligible plan (HDHP) vs. a traditional plan: total yearly cost for one level of medical
  // spending. For each plan:
  //   out-of-pocket = min(out-of-pocket max, min(spending, deductible)
  //                       + coinsurance x max(0, spending - deductible))
  //   cost          = 12 x monthly premium (x (1 - tax rate) if premiums are taken pre-tax)
  //                   + out-of-pocket + other costs (copays etc.)
  // HSA plan net cost = cost - employer HSA contribution - tax saved on your HSA contribution,
  // where tax saved = your contribution x (federal + state rate, + 7.65% FICA through payroll) and
  // your contribution is capped at the 2026 limit minus the employer's contribution.
  // CHECKS (Node, scratch tests): spending $3,000, HDHP $150/mo, $3,000 deductible, 20%, $6,000
  // max -> premiums $1,800 + OOP $3,000 = $4,800, less employer $500 and tax saved on $2,000 at
  // 22% + 5% + 7.65% ($693) = $3,607; traditional $300/mo, $1,000 deductible, 20%, $4,000 max ->
  // $3,600 + 1,000 + 0.2 x 2,000 = $5,000. Spending $100,000 -> both plans stop at their
  // out-of-pocket max; $0 spending -> premiums only; 0% coinsurance -> OOP = min(spend, ded);
  // self-only contribution $5,000 with $500 employer is capped at $3,900 ($4,900 at 55+).
  // ---- 2026 HSA LIMITS (calendar year 2026) ---------------------------------------------------
  // Source: IRS Rev. Proc. 2025-19 (IRC 223 inflation adjustments for 2026). Catch-up: IRC
  // 223(b)(3)(B), a fixed $1,000 for account holders 55 or older (not indexed; IRS Pub. 969).
  // FICA: 6.2% Social Security + 1.45% Medicare employee rates (IRC 3101).
  var HSA = {
    year: 2026,
    limit: { self: 4400, family: 8750 },
    catchUp55: 1000,
    hdhpMinDeductible: { self: 1700, family: 3400 },
    hdhpOutOfPocketMax: { self: 8500, family: 17000 }
  };
  var FICA_RATE = 0.0765;
  // --------------------------------------------------------------------------------------------

  function outOfPocket(spend, ded, coins, oopMax) {
    if (!(spend > 0)) return 0;
    return Math.min(oopMax, Math.min(spend, ded) + coins * Math.max(0, spend - ded));
  }

  // plan: premium (monthly), ded, coins (decimal), oop, other
  function planCost(plan, spend, premFactor) {
    var prem = plan.premium * 12 * premFactor, oop = outOfPocket(spend, plan.ded, plan.coins, plan.oop);
    return { premiums: prem, oop: oop, other: plan.other, gross: prem + oop + plan.other };
  }

  // p: hsa, trad (plans), spend, coverage, age55, contrib, employer, hsaRate, premRate (decimals)
  function compare(p) {
    var lim = HSA.limit[p.coverage] + (p.age55 ? HSA.catchUp55 : 0);
    var er = Math.min(p.employer, lim);
    var you = Math.min(p.contrib, Math.max(0, lim - er));
    var premFactor = 1 - p.premRate;
    var h = planCost(p.hsa, p.spend, premFactor), t = planCost(p.trad, p.spend, premFactor);
    var taxSaved = you * p.hsaRate;
    h.employer = er; h.taxSaved = taxSaved; h.net = h.gross - er - taxSaved;
    t.employer = 0; t.taxSaved = 0; t.net = t.gross;
    return { hsa: h, trad: t, you: you, limit: lim,
             capped: p.contrib > you + 0.005 || p.employer > lim + 0.005 };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fillRows(id, rows) {
    var body = document.getElementById(id);
    body.textContent = '';
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }
  function readPlan(prefix) {
    return { premium: num(prefix + 'Prem'), ded: num(prefix + 'Ded'), coins: num(prefix + 'Coins'),
             oop: num(prefix + 'Oop'), other: num(prefix + 'Other') };
  }

  function update() {
    var hsa = readPlan('hvH'), trad = readPlan('hvT');
    var coverage = document.getElementById('hvCoverage').value, age55 = document.getElementById('hvAge55').checked;
    var spend = num('hvSpend'), contrib = num('hvContrib'), employer = num('hvEmployer'),
        fed = num('hvFed'), state = num('hvState');
    var payroll = document.getElementById('hvPayroll').checked, preTax = document.getElementById('hvPreTax').checked;
    var error = document.getElementById('hvError');
    var vals = [hsa.premium, hsa.ded, hsa.coins, hsa.oop, hsa.other, trad.premium, trad.ded, trad.coins, trad.oop,
                trad.other, spend, contrib, employer, fed, state];
    var msg = '';
    if (vals.some(isNaN) || vals.some(function (v) { return v < 0; })) msg = 'Enter non-negative amounts in every field.';
    else if (hsa.coins > 100 || trad.coins > 100) msg = 'Coinsurance must be between 0 and 100%.';
    else if (fed > 37 || state > 15) msg = 'Enter a federal rate up to 37% and a state rate up to 15%.';
    else if (hsa.oop < hsa.ded || trad.oop < trad.ded) msg = 'Each plan\'s out-of-pocket maximum must be at least its deductible.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }
    hsa.coins /= 100; trad.coins /= 100;
    var incomeRate = fed / 100 + state / 100;
    var base = { hsa: hsa, trad: trad, coverage: coverage, age55: age55, contrib: contrib, employer: employer,
                 hsaRate: incomeRate + (payroll ? FICA_RATE : 0), premRate: preTax ? incomeRate + FICA_RATE : 0 };
    function run(s) { base.spend = s; return compare(base); }
    var r = run(spend);
    set('hvHsaNet', money(r.hsa.net));
    set('hvTradNet', money(r.trad.net));
    var diff = r.trad.net - r.hsa.net;
    set('hvDiffLabel', Math.abs(diff) < 0.5 ? 'Difference' : (diff > 0 ? 'HSA plan saves you' : 'Traditional plan saves you'));
    set('hvDiff', money(Math.abs(diff)));
    fillRows('hvBreakdown', [
      ['Premiums' + (preTax ? ' (after tax savings)' : ''), money(r.hsa.premiums), money(r.trad.premiums)],
      ['Deductible and coinsurance', money(r.hsa.oop), money(r.trad.oop)],
      ['Copays and other costs', money(r.hsa.other), money(r.trad.other)],
      ['Employer HSA contribution', r.hsa.employer > 0.5 ? '−' + money(r.hsa.employer) : money(0), '–'],
      ['Tax saved on your HSA contribution', r.hsa.taxSaved > 0.5 ? '−' + money(r.hsa.taxSaved) : money(0), '–'],
      ['Net yearly cost', money(r.hsa.net), money(r.trad.net)]
    ]);
    set('hvContribNote', 'Your HSA contribution used: ' + money(r.you) + ' of a ' + HSA.year + ' limit of ' + money(r.limit) +
        ' (' + (coverage === 'family' ? 'family' : 'self-only') + (age55 ? ', with catch-up' : '') + ').');
    var capEl = document.getElementById('hvCapped');
    capEl.hidden = !r.capped;
    if (r.capped) capEl.textContent = 'Your contribution plus your employer\'s is above the ' + HSA.year +
        ' limit, so the comparison counts only ' + money(r.you) + ' from you.';
    var ded = HSA.hdhpMinDeductible[coverage], maxOop = HSA.hdhpOutOfPocketMax[coverage];
    var hdhpEl = document.getElementById('hvHdhp');
    var notHdhp = hsa.ded < ded || hsa.oop > maxOop;
    hdhpEl.hidden = !notHdhp;
    if (notHdhp) hdhpEl.textContent = 'For ' + HSA.year + ', an HSA-eligible plan with ' +
        (coverage === 'family' ? 'family' : 'self-only') + ' coverage needs a deductible of at least ' + money(ded) +
        ' and an out-of-pocket maximum of no more than ' + money(maxOop) + '. Bronze and catastrophic plans offered as individual coverage on a health insurance Exchange also qualify from 2026 even if they fall outside these limits. Check that your plan qualifies.';
    var levels = [0, 1000, 2500, 5000, 10000, 25000, 50000];
    if (levels.indexOf(spend) < 0) levels.push(spend);
    levels.sort(function (a, b) { return a - b; });
    fillRows('hvScenarios', levels.map(function (s) {
      var x = run(s), d = x.trad.net - x.hsa.net;
      return [money(s) + (s === spend ? ' (yours)' : ''), money(x.hsa.net), money(x.trad.net),
              Math.abs(d) < 0.5 ? 'Same cost' : (d > 0 ? 'HSA plan by ' : 'Traditional by ') + money(Math.abs(d))];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('hvForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
